import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n = int(input())
        f = [[0] * 101 for i in range(101)]
        for i in range(n):
            a, b, c, d = map(int, input().split())
            for x in range(a, b):
                for y in range(c, d):
                    f[x][y] = 1
        ans = 0
        for i in range(101):
            ans += sum(f[i])
