import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        import sys
        sys.setrecursionlimit(10 ** 7)

        def input():
            return sys.stdin.readline().rstrip()

        def main():
            N, M = map(int, input().split())
            B = [list(map(int, input().split())) for _ in range(N)]
            start = B[0][0]
            # Check if start is valid: the column index should match the modulo 7 offset
            # The problem's condition is that for each B[i][j], (B[i][j] - start) == i*7 + j
            # But first check if the modulo 7 values align with columns
            # The modulo 7 of start should be consistent with the first column (j=0)
            # So for each element, (B[i][j] - start) % 7 == j
            for i in range(N):
                for j in range(M):
                    if (B[i][j] - start) % 7 != j:
                        print('No')
                        return
            # Also check that the rows are consecutive by 7
            # i.e. B[i][0] == start + i*7
            for i in range(N):
                if B[i][0] != start + i * 7:
                    print('No')
                    return
            print('Yes')

        main()
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

