import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        H, W, K = map(int, input().split())
        S = [input() for i in range(H)]
        dic = dict({'o': 0, 'x': 1, '.': 2})
        ans = 10 ** 10
        for i in range(H):
            if W < K:
                break
            chk = [0, 0, 0]
            for j in range(K):
                chk[dic[S[i][j]]] += 1
            if chk[1] == 0:
                ans = min(ans, chk[2])
            for j in range(K, W):
                chk[dic[S[i][j - K]]] -= 1
                chk[dic[S[i][j]]] += 1
                if chk[1] == 0:
                    ans = min(ans, chk[2])
        for j in range(W):
            if H < K:
                break
            chk = [0, 0, 0]
            for i in range(K):
                chk[dic[S[i][j]]] += 1
            if chk[1] == 0:
                ans = min(ans, chk[2])
            for i in range(K, H):
                chk[dic[S[i - K][j]]] -= 1
                chk[dic[S[i][j]]] += 1
                if chk[1] == 0:
                    ans = min(ans, chk[2])
        if ans == 10 ** 10:
            print(-1)
        else:
            print(ans)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

