import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        A, M, L, R = map(int, input().split())
        if M == 0:
            print(0)
            return
        # Calculate the smallest x such that A + M*x >= L
        x1 = (L - A + (M - 1)) // M if M > 0 else (L - A) // M
        # Calculate the largest x such that A + M*x <= R
        x2 = (R - A) // M if M > 0 else (R - A + (M + 1)) // M
        if x1 > x2:
            print(0)
        else:
            print(x2 - x1 + 1)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

