import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, m = map(int, input().split())
        s = 0
        d = {}
        for i in range(n):
            a, b = map(int, input().split())
            s += a
            diff = b - a
            if diff not in d:
                d[diff] = 0
            d[diff] += 1
        p = []
        for dd in d:
            count = d[dd]
            pp = 1
            while pp <= count:
                p.append((dd, pp))
                count -= pp
                pp *= 2
            if count > 0:
                p.append((dd, count))
        q = [n + 1] * (m + 1)
        q[s] = 0
        for dd, pp in p:
            nq = q[:]
            for i in range(m + 1):
                if q[i] < n + 1:
                    # keep current
                    if nq[i] > q[i]:
                        nq[i] = q[i]
                    # try to add dd * pp if valid
                    ni = i + dd * pp
                    if 0 <= ni <= m:
                        if nq[ni] > q[i] + pp:
